import{_ as a,c as n,o as e,a4 as t}from"./chunks/framework.iMXuyU9c.js";const _=JSON.parse('{"title":"排列组合","description":"","frontmatter":{},"headers":[],"relativePath":"算法/排列组合.md","filePath":"算法/排列组合.md"}'),r={name:"算法/排列组合.md"},o=t(`<h1 id="排列组合" tabindex="-1">排列组合 <a class="header-anchor" href="#排列组合" aria-label="Permalink to &quot;排列组合&quot;">​</a></h1><pre><code>该文创建于 2024/07/09
</code></pre><p>文章参考 <a href="https://baike.baidu.com/item/%E6%8E%92%E5%88%97%E7%BB%84%E5%90%88/706498?fr=ge_ala" target="_blank" rel="noreferrer">百度百科</a></p><p>此外规定0! = 1</p><p>公式 <img src="https://bkimg.cdn.bcebos.com/formula/ac0926e610dce08b12a0c0c42b835cb0.png" alt="排列" loading="lazy"></p><h2 id="排列-arrangement" tabindex="-1">排列(Arrangement) <a class="header-anchor" href="#排列-arrangement" aria-label="Permalink to &quot;排列(Arrangement)&quot;">​</a></h2><p><strong>定义</strong> : 从n个不同元素中，任取m（m≤n,m与n均为自然数,下同）个不同的元素按照一定的顺序排成一列，叫做从n个不同元素中取出m个元素的一个排列； 从n个不同元素中取出m（m≤n）个元素的所有排列的个数，叫做从n个不同元素中取出m个元素的排列数，用符号 <strong>A(n,m)</strong> 或<img src="https://bkimg.cdn.bcebos.com/formula/cb858d2bd03358624fd93c5a482539f6.png" alt="" loading="lazy">表示。</p><p><strong>计算公式</strong> A(n,m) = n(n-1)(n-2)...(n-m+1) = n! / (n-m)! <img src="https://bkimg.cdn.bcebos.com/formula/ac0926e610dce08b12a0c0c42b835cb0.png" alt="排列" loading="lazy"></p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><p><strong>定义</strong> : 从n个不同元素中，任取m（m≤n）个元素并成一组，叫做从n个不同元素中取出m个元素的一个组合； 从n个不同元素中取出m（m≤n）个元素的所有组合的个数，叫做从n个不同元素中取出m个元素的组合数。用符号 <strong>C(n,m)</strong> 表示。</p><p><strong>计算公式</strong> C(n,m) = A(n,m) / m! = n! / m!(n-m)! C(n,m) == C(n, n-m), 其中 n&gt;=m。 <img src="https://bkimg.cdn.bcebos.com/formula/620a7d43cbc2c75ca47802b017929910.png" alt="组合" loading="lazy"><img src="https://bkimg.cdn.bcebos.com/formula/e7c3366acf00b8d611cd99ac5f14ea18.png" alt="组合" loading="lazy"></p>`,11),c=[o];function m(s,l,d,i,g,p){return e(),n("div",null,c)}const h=a(r,[["render",m]]);export{_ as __pageData,h as default};
